import com.example.price_tag.ui.features.home.widgets.CarouselSlider
import com.example.utilites.ResourceState

@OptIn(ExperimentalMaterial3Api::class,
       ExperimentalFoundationApi::class)
@Composable
fun ProductDetailsView(
    navController: NavController,
    paddingValues: PaddingValues,
    productDetailsViewModel: ProductDetailsViewModel,
    selectedCategoryViewModel: SelectedCategoryViewModel,
    productId: Long?,
) {
    val images = listOf(
        CarouselItem(R.drawable.carousel1),
        CarouselItem(R.drawable.carousel2),
        CarouselItem(R.drawable.carousel3),
    )
    val pagerState = rememberPagerState(pageCount = { images.size })
    val coroutineScope = rememberCoroutineScope()

    var selectedColor by rememberSaveable {
        mutableStateOf<String?>(null)
    }
    var selectedSize by rememberSaveable {
        mutableStateOf<Int?>(null)
    }
    var selectedVariant by rememberSaveable {
        mutableStateOf<ProductVariants?>(null)
    }

    var selectedTabIndex by rememberSaveable { mutableIntStateOf(0) }
    val tabs = listOf(
        "Description",
        "Reviews",
    )

    val getSingleProductDetailsData =
        productDetailsViewModel.getSingleProductDetailsData.collectAsStateWithLifecycle()

    LaunchedEffect(true) {
        if (productId != null) {
            productDetailsViewModel.getSingleProductDetails(productId = productId)
        }
    }

    Scaffold(modifier = Modifier
        .padding(horizontal = 16.dp)
        .systemBarsPadding(),
             topBar = {
                 CenterAlignedTopAppBar(navigationIcon = {
                     IconButton(onClick = { navController.popBackStack() },
                                modifier = Modifier
                                    .border(shape = CircleShape.copy(CornerSize(percent = 100)),
                                            border = BorderStroke(width = 1.dp,
                                                                  color = NeutralColor200))
                                    .size(35.dp)) {
                         Icon(imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                              contentDescription = "Back")
                     }
                 },
                                        title = {
                                            Text(
                                                text = "Product Details",
                                                fontFamily = Poppins,
                                                fontSize = 22.sp,
                                                fontWeight = FontWeight.SemiBold,
                                            )
                                        },
                                        actions = {
                                            CartIconWithBadge()
                                        })
             },

             bottomBar = {
                 BottomAppBar(
                     modifier = Modifier
                         .height(60.dp)
                         .fillMaxWidth(),
                     containerColor = Color.Transparent,
                 ) {
                     Row(modifier = Modifier.fillMaxWidth(),
                         horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                         Button(onClick = { /*TODO*/ },
                                modifier = Modifier.weight(1f),
                                colors = ButtonColors(
                                    containerColor = PrimaryColor,
                                    contentColor = Color.White,
                                    disabledContentColor = NeutralColor800,
                                    disabledContainerColor = NeutralColor100,
                                )) {
                             Text(text = "Buy Now")
                         }
                         Button(onClick = { /*TODO*/ },
                                modifier = Modifier.weight(1f),
                                colors = ButtonColors(
                                    containerColor = PrimaryColor,
                                    contentColor = Color.White,
                                    disabledContentColor = NeutralColor800,
                                    disabledContainerColor = NeutralColor100,
                                )) {
                             Text(text = "Add to Cart")
                         }

                     }
                 }
             }

    ) { innerPadding ->

        when (getSingleProductDetailsData.value) {
            is ResourceState.Loading -> {
                Box(modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center) {
                    CircularProgressIndicator(modifier = Modifier.padding(paddingValues))
                }
            }

            is ResourceState.Success -> {
                val productDetails: SingleProductDetails =
                    (getSingleProductDetailsData.value as ResourceState.Success<SingleProductDetails>).data
                val colorSizeVariantGroup: List<ColorSizeVariantGroup> =
                    productDetails.colorSizeVariantGroup ?: emptyList()
                selectedColor = selectedColor ?: colorSizeVariantGroup.firstOrNull()?.colorHex
                selectedSize = selectedSize ?: colorSizeVariantGroup.firstOrNull {
                    it.colorHex == selectedColor
                }?.variants?.firstOrNull()?.size?.id?.toInt()
                selectedVariant = selectedVariant ?: colorSizeVariantGroup.firstOrNull {
                    it.colorHex == selectedColor
                }?.variants?.firstOrNull { it.size?.id?.toInt() == selectedSize }

                LazyColumn(modifier = Modifier
                    .padding(innerPadding)
                    .fillMaxSize(),
                           verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    item {
                        CarouselSlider(
                            images = images,
                            pageCount = images.size,
                            pagerState = pagerState,
                            coroutine = coroutineScope,
                        )
                    }

                    item {
                        Row {
                            StarRating(rating = 4)
                            Spacer(modifier = Modifier.width(10.dp))
                            Text(text = "20 Reviews",
                                 fontSize = 12.sp)
                        }
                    }

                    item {
                        Row(modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                text = productDetails.name ?: "",
                                fontSize = 18.sp,
                                fontWeight = FontWeight.SemiBold,
                            )

                            Spacer(modifier = Modifier.width(10.dp))

                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.End,
                            ) {
                                IconButton(
                                    onClick = { /*TODO*/ },
                                    modifier = Modifier
                                        .clip(shape = CircleShape)
                                        .size(36.dp)
                                        .background(color = PrimaryColor50),
                                ) {
                                    Icon(
                                        imageVector = Icons.Outlined.FavoriteBorder,
                                        contentDescription = "Favorite",
                                        tint = PrimaryColor600,
                                    )
                                }

                                Spacer(modifier = Modifier.width(10.dp))

                                IconButton(
                                    onClick = { /*TODO*/ },
                                    modifier = Modifier
                                        .clip(shape = CircleShape)
                                        .size(36.dp)
                                        .background(color = PrimaryColor50),
                                ) {
                                    Icon(
                                        imageVector = Icons.Outlined.Share,
                                        contentDescription = "Share",
                                        tint = PrimaryColor600,
                                    )
                                }

                            }
                        }
                    }

                    item {
                        Text(text = productDetails.description ?: "Short Description",
                             fontSize = 18.sp,
                             fontWeight = FontWeight.SemiBold)
                    }

                    item {
                        HorizontalDivider(color = NeutralColor200)
                    }

                    item {
                        Text(
                            text = "Select Color",
                            fontSize = 18.sp,
                        )

                        Spacer(modifier = Modifier.height(10.dp))

                        LazyRow(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            items(items = colorSizeVariantGroup) { data ->
                                Box(
                                    modifier = Modifier
                                        .size(30.dp)
                                        .clip(CircleShape)
                                        .background(Color(data.colorHex.toColorInt()))
                                        .border(
                                            width = 2.dp,
                                            color = if (data.colorHex == selectedColor) PrimaryColor else NeutralColor100,
                                            shape = CircleShape,
                                        )
                                        .clickable {
                                            selectedColor = data.colorHex
                                            selectedSize = null
                                            selectedVariant = null
                                        },
                                )
                            }
                        }
                    }


                    if (selectedColor?.isNotEmpty() == true) item {
                        Text(
                            text = "Select Size",
                            fontSize = 18.sp,
                        )

                        Spacer(modifier = Modifier.height(10.dp))

                        val selectedGroup: ColorSizeVariantGroup? =
                            colorSizeVariantGroup.firstOrNull { it.colorHex == selectedColor }

                        LazyRow(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            items(selectedGroup?.variants ?: emptyList()) { productVariant ->
                                Box(
                                    modifier = Modifier
                                        .size(30.dp)
                                        .clip(shape = RoundedCornerShape(percent = 15))
                                        .clickable {
                                            selectedSize = productVariant.size?.id?.toInt()
                                            selectedVariant = productVariant
                                        }
                                        .background(color = if (selectedSize == productVariant.size?.id?.toInt()) PrimaryColor else Color.Transparent)
                                        .border(
                                            shape = RoundedCornerShape(percent = 15),
                                            width = 2.dp,
                                            color = NeutralColor100,
                                        ),
                                    contentAlignment = Alignment.Center,
                                ) {
                                    Text(
                                        text = productVariant.size?.name ?: "",
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = if (selectedSize == productVariant.size?.id?.toInt()) Color.White else NeutralColor800,
                                    )
                                }
                            }
                        }
                    }

                    item { Spacer(modifier = Modifier.height(10.dp)) }

                    item { Spacer(modifier = Modifier.height(10.dp)) }

                    stickyHeader { // Tab Row at the top
                        TabRow(
                            selectedTabIndex = selectedTabIndex,
                            modifier = Modifier.fillMaxWidth(),
                            indicator = {},
                            divider = {},
                        ) {
                            tabs.forEachIndexed { index, title ->
                                Tab(selected = selectedTabIndex == index,
                                    onClick = { selectedTabIndex = index },
                                    text = { Text(title) },
                                    selectedContentColor = Color.White,
                                    unselectedContentColor = NeutralColor800,
                                    modifier = Modifier //                                .size(40.dp)
                                        .clip(shape = RoundedCornerShape(8.dp))
                                        .background(color = if (selectedTabIndex == index) PrimaryColor else Color.Transparent))
                            }
                        }
                    }

                    item {
                        when (selectedTabIndex) {
                            0 -> DescriptionContent()
                            1 -> ReviewContent()
                        }
                    }

                }
            }

            is ResourceState.Error -> {
                val error = (getSingleProductDetailsData.value as ResourceState.Error).error
                Box(modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)) {
                    Text(text = error,
                         color = Color.Red,
                         fontSize = 18.sp)
                }
            }

            else -> {}
        }
    }

}

@Composable
fun DescriptionContent() {
    Text(text = "This is the product description. It explains the product details, features, and specifications.",
         modifier = Modifier.padding(8.dp))
}

@Composable
fun ReviewContent() {
    for (i in 1..8) {
        Box(modifier = Modifier.padding(bottom = 8.dp)) {
            Column(
                modifier = Modifier
                    .border(width = 1.dp,
                            color = NeutralColor200,
                            shape = RoundedCornerShape(8.dp))
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically) {
                    Image(
                        painter = painterResource(id = R.drawable.carousel1),
                        contentDescription = "",
                        contentScale = ContentScale.Crop,
                        modifier = Modifier
                            .size(50.dp)
                            .clip(CircleShape),
                    )
                    Column(
                        verticalArrangement = Arrangement.spacedBy(4.dp),
                        horizontalAlignment = Alignment.Start,
                    ) {
                        Text(text = "User Name")
                        Text(text = "⭐️⭐️⭐️⭐️️")
                    }
                }
                Text(text = "This is the product review. It explains the product details, features, and specifications.")

            }
        }
    }
}

